def fib(n, memo={}):
    if n in memo:
        return memo[n]
    if n < 2:
        return n
    memo[n] = fib(n - 1, memo) + fib(n - 2, memo)
    return memo[n]
# without the memo dictionary the naive version recomputes the same values exponentially often

haeufigkeit = {}
with open("text.txt", encoding="utf-8") as f:
    for zeile in f:
        for wort in zeile.lower().split():
            haeufigkeit[wort] = haeufigkeit.get(wort, 0) + 1
for wort, anzahl in sorted(haeufigkeit.items(), key=lambda p: -p[1])[:10]:
    print(wort, anzahl)
